const path = require('path');
const { pathToFileURL } = require('url');
const { chromium } = require('/tmp/cat-faq-a11y/node_modules/playwright');
const axe = require('/tmp/cat-faq-a11y/node_modules/axe-core');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto(pathToFileURL(path.resolve('index.html')).href, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });

  async function audit(label) {
    const results = await page.evaluate(async () => await window.axe.run(document, {
      resultTypes: ['violations'],
      runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa', 'best-practice'] }
    }));
    return {
