      violations: results.violations.map((v) => ({
        id: v.id,
        impact: v.impact,
        tags: v.tags,
        targets: v.nodes.map((n) => n.target)
      }))
    };
  }

  const collapsed = await audit('collapsed');
  await page.locator('.question button').evaluateAll((buttons) => buttons.forEach((button) => button.click()));
  const expanded = await audit('expanded');
  await browser.close();

  const all = [collapsed, expanded];
  const wcag = all.flatMap((run) => run.violations
    .filter((v) => !v.tags.includes('best-practice'))
    .map((v) => ({ run: run.label, id: v.id, impact: v.impact, targets: v.targets })));
  const bp = all.flatMap((run) => run.violations
    .filter((v) => v.tags.includes('best-practice'))
    .map((v) => ({ run: run.label, id: v.id, impact: v.impact, targets: v.targets })));

  console.log(JSON.stringify({ wcag, bestPractice: bp }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
